  "status.faceToolFailed": "面ツールでこのボディを作れませんでした: {message}",
  "status.honeycombConverted": "ハニカムを穴パターンに変換しました: {count}",
  "welcome.moreHolePatternTitle": "穴パターン",
  "welcome.moreHolePatternBody": "ボディの平らな面をクリックして、穴を面全体に広げます。丸、正方形、長方形、六角形、長穴を格子状または千鳥状に並べ、間隔、エッジまでの余白、深さ（ボディ全体を貫通、または決めた深さ）を設定できます。作成前にプレビューで穴を確認できます。作成した穴は通常の穴のままで、ボディとグループ化されます。通気口、スピーカーグリル、かご、ケースなどに便利です。 または、縁に沿ってねじ穴を一周並べることもできます。角ごとに1つ、必要ならざぐりや皿もみ付きで。 同じように自分の形状も繰り返せます。リベットや縞鋼板などに。 円柱やパイプの側面では、穴が一周し、それぞれ軸に向かいます。",
  "welcome.moreSupportRibTitle": "サポートリブ",
  "welcome.moreSupportRibBody": "エッジで斜めに立てたパーツをスライサーのサポートなしで印刷: 下面をクリックすると、細いリブが少し離れて楕円の足の上に立ち、ちょうど 1 層の小さなブリッジがパーツを支え、あとで折り取れます。",
  "welcome.moreStencilBridgesTitle": "ステンシルブリッジ",
  "welcome.moreStencilBridgesBody": "文字を貫通させたステンシルを印刷: o、a、b などの文字の内側に、好きな幅と高さの小さなブリッジがプレートまで付き、何も抜け落ちません。",
  "welcome.moreFaceTitle": "面を押し出す",
  "welcome.moreFaceBody": "ボディの平らな面を押し出したりポケットを彫り込んだりできます。縁からのオフセット、角の丸め、深さを指定し、プレビューで確認。読み込んだ STL にも使えます。",
  "welcome.moreTextureTitle": "表面テクスチャ",
  "welcome.moreTextureBody": "どんなボディにも、すべり止めや見た目のために凹凸を付けます。ローレット、みぞ、ハニカム、レンガ、カーボン、木の皮、木目、ロープ、高さマップとしての画像や文字を、丸いボディのまわりにも、軸にそって平らにも付けられます。1つのボディに模様を6つまで、それぞれ別の面に付けられます。2色でプリントするときは、模様を別のパーツにして、別の色にすることもできます。",
  "welcome.moreVaseTitle": "花びんと鉢",
  "welcome.moreVaseBody": "花びん、植木鉢、ランプシェード専用のシェイプです。形、断面、ねじれ、模様、水ぬきの穴、受け皿、ふたを選べます。スライサーの花びんモード用にソリッドで作ることも、中空で作ることもできます。ティーポットのふたは花びんの上の部分をそのまま使い、模様がつなぎ目をこえて続きます。",
  "welcome.moreOffsetTitle": "オフセットと切りぬき",
  "welcome.moreOffsetBody": "正確なボディを、決めた距離だけ大きくしたり小さくしたりします。全体でも横だけでもでき、圧入のすき間に使えます。1つのパーツから別のパーツを、まわりにすき間をあけて1回で切りぬくこともできます。",
  "guide.select.holePattern": "穴パターン（リボンのパターンの隣のボタン、ボディの右クリック、または Ctrl+K）: 平らな面か円筒の側面をクリックし、穴のシェイプ、サイズ、間隔、配置、余白、深さを設定します。穴はプレビューとして表示され、「作成」でボディとグループ化された穴として追加されます。グループ解除で再び自由になります。",
  "guide.select.faceTool": "面（リボンの穴パターンの隣のボタン、ボディの右クリック、または Ctrl+K）: 平らな面をクリックし、「外」か「内」を選んで、エッジからの余白、角の半径、深さを決めます。足されるものは、ボディとグループ化されたスケッチボディです。",
  "guide.select.supportRib": "サポートリブ（リボンのボタン、ボディの右クリック、または Ctrl+K）: エッジで斜めに立てて印刷するパーツの下面をクリックします。細いリブが少し離れて下に立ち、楕円の足の上で、1 層の高さの小さなブリッジでパーツに留まります。スライサーのノズルと積層を設定してください。",
  "scalePercent.errorTooSmall": "「{name}」が0.01 mmより小さくなってしまいます。",
