  "status.meshTooDense": "このメッシュは{triangles}個の三角形でできています。このツールで扱えるのは{limit}個までで、それより大きいとカーネルの処理に時間がかかりすぎます。シェイプライブラリのシェイプなら、まずそのシェイプ自身の設定を使ってください。読み込んだパーツなどほかのメッシュは、右クリックして「メッシュを簡略化」で三角形を減らせます。読み込んだパーツはSTEPとして読み込むこともできます。",
  "status.meshDenseAsk": "このメッシュには{triangles}個の三角形があり、このツールが想定している{limit}個より多いです。それ以上だと何分もかかり、ページが止まることがあります。そのときページを閉じると、保存していないものは消えてしまいます。先にデザインを保存してください。それでもやってみますか？",
  "status.threadTooDense": "ねじは{triangles}個の三角形でできていて、エッジ処理の上限{limit}個より大きくなっています。ねじは、エッジ処理のあとに追加してください。先にボディを面取り（角をななめに切る）またはフィレットにしてから、ねじを追加します。プロパティの「頭部の面取り」を使えば、この手順なしでねじ頭の縁を落とせます。",
  "status.unlockImageDelete": "消す前に L でスケッチ画像のロックを解除してください",
