  "status.cutTooComplex": "このシェイプは複雑すぎて切り抜けません: 三角形が{triangles}個で、上限は{limit}個です。先にメッシュを簡略化（デシメート）するか、ワークスペース設定で上限を上げてください。",
  "status.groupNotMerged": "グループ化しましたが、1つのソリッドにはまとめていません。パーツの三角形が合わせて{triangles}個あり、上限の{limit}個より多いためです。エクスポートでは重なったままになり、スライサーがエラー（非多様体エッジ）と報告します。ワークスペース設定で上限を上げるか、メッシュを簡略化してから、もう一度グループ化してください。",
