  "thread.flankAngleHint": "ねじ山の2つの斜面がつくる角度です。60°はとがったV形のねじ、30°は台形ねじです。90°以下だと、45°よりなだらかな斜面がないので、サポートなしでプリントできます。",
  "thread.startsHint": "リードスクリューのように複数の条が並びます。T8x8 は 2 mm ピッチの 4 条です。1 は通常のねじです。",
  "thread.startsLeadHint": "各条は 1 回転で {lead} mm 進みます（{starts} × {pitch} mm）。",
  "prop.clearance": "クリアランス (XY)",
  "prop.threadChamferTop": "面取り、上端",
  "prop.threadChamferBottom": "面取り、下端",
  "thread.axialClearanceHint": "クリアランスに加えて、ねじの軸方向に与える余分な遊び（mm）です。直径はそのままで、ナットの各歯がこの分だけ薄くなります。横にがたつかずに軽く回るねじにするには、クリアランスを0.2〜0.3程度にして、ここに0.2を決めます。0ではクリアランスだけで遊びが決まり、フランクの開きはその半分程度にしかなりません。",
  "thread.clearanceHint": "直径全体に加える余分な空間です。プリントしたねじには思ったより多く必要です。フランク間のすき間はこの約半分にしかなりません。0.3程度できつめ、0.4が標準、0.5でゆるめです。まずテスト用の組を印刷してください。",
  "thread.boltClearanceHint": "自身に遊びのない金属ナット向けに、ボルトをこの分だけ細くします（0.3〜0.4、プリントしたナットが持つ程度の量）。プリントしたナットを使う場合は0のままにして、ナット側に余裕を持たせてください。",
