  "prop.washerSize": "ワッシャー",
  "prop.washerSizeHint": "このねじサイズのワッシャーの外径・内径・厚さを ISO 7089 に合わせて設定します。",
  "prop.screwHoleSize": "ねじサイズ",
  "prop.screwHoleSizeCounterboreHint": "このサイズの六角穴付きボルトに合わせて、軸径・頭部径・深さを設定します。通し穴は ISO 273（中級）、座ぐりは DIN 974-1。長さはそのままです。",
  "prop.screwHoleSizeCountersinkHint": "このサイズの皿ねじに合わせて、軸径と頭部径を設定します。通し穴は ISO 273（中級）、皿もみは ISO 15065・90°。インチサイズ #2〜#14 は ASME B18.6.1・82°（オーストラリアのゲージにも対応、6-gauge = #6）。長さはそのままです。",
  "prop.nutPocketSize": "ナット用くぼみ",
  "prop.nutPocketSizeHint": "六角形をこのねじサイズの六角ナット（ISO 4032）用のくぼみにします。ナットより 0.4 mm 広く高くなります。穴にするとくぼみを切り抜きます。",
