  "prop.hingeClearance": "クリアランス",
  "prop.hingeCornerRadius": "角の半径",
  "prop.hingeLeafStyle": "羽根の形",
  "hinge.leafPlate": "板",
  "hinge.leafFingers": "指",
  "hinge.leafFingersHint": "ナックルごとに自分の指が付き、両側の指が2つのくしのように交互にならびます。だから、ヒンジはぐるっと最後まで折れ、円すい付きで指をナックルと同じ厚さにすると、閉じたときに平らになります。片側の指どうしをつなぐ羽根はありません。箱とそのふたのように、自分のモデルにつないでください。",
  "prop.hingeScrewHoles": "羽根1枚あたりのねじ穴",
  "prop.hingeScrewHolesHint": "0なら羽根に穴をあけません。",
  "prop.hingeScrewHolesFewer": "羽根には{count}個しか入りません。",
  "prop.hingeScrewDiameter": "穴の直径",
  "prop.hingeScrewHead": "穴",
  "hinge.screwCountersunk": "皿もみ",
  "hinge.screwStraight": "まっすぐ",
  "hinge.screwCountersunkHint": "皿ねじ用です。ヒンジを閉じたときに、もう片方の羽根に向く側にあけます。",
  "prop.hingeScrewSpacing": "穴の間かく（軸方向）",
  "prop.hingeScrewSpacingHint": "軸にそった、穴の中心から次の穴の中心までです。0なら長さ全体に同じ間かくで穴をならべます。",
  "prop.hingeScrewAcross": "穴の間かく（横方向）",
  "prop.hingeScrewAcrossHint": "片方の羽根の穴から、もう片方の羽根の穴までの、中心から中心までです。0ならそれぞれの穴を羽根のまん中にあけます。",
  "prop.gridfinityType": "種類",
  "gridfinity.bin": "ビン",
  "gridfinity.baseplate": "ベースプレート",
  "gridfinity.binHint": "42 mmのGridfinityグリッドに合うビンです。ベースプレートにはまり、ほかのビンの上に重ねられます。ほかのGridfinityジェネレーターで作ったビンにも重ねられます。Gridfinityは、Zack Freedmanによるオープンな収納システムで、MITライセンスで公開されています。layerlingは公開された寸法をもとに対応するパーツを作るもので、Gridfinityプロジェクトの一部ではありません。",
  "gridfinity.baseplateHint": "Gridfinityのビンをのせる、高さ5 mmのプレートです。42 mmのグリッド1つにつき、くぼみが1つあります。Gridfinityは、Zack Freedmanによるオープンな収納システムで、MITライセンスで公開されています。layerlingは公開された寸法をもとに対応するパーツを作るもので、Gridfinityプロジェクトの一部ではありません。",
  "gridfinity.tray": "トレイ",
  "gridfinity.trayHint": "平らな底の、mm単位で好きな大きさのトレイです。ボードゲームの収納や小物入れに使えます。脚も重ねるためのふちもないので、ベースプレートには置けず、重ねられません。仕切りとラベル棚は上端まで届きます。",
  "gridfinity.compartmentsTrayHint": "トレイでは仕切りが上のはしまで立ちます。どの区画も幅が6 mm以上になります。",
  "prop.gridfinityUnitsX": "横のマス数",
  "prop.gridfinityUnitsZ": "奥行きのマス数",
  "prop.gridfinityUnitsY": "高さのマス数",
  "prop.gridfinityLip": "重ねるためのふち",
  "prop.gridfinityLipChamfer": "ふちの面取り",
  "gridfinity.lipChamferHint": "重ねるためのふちの、上のエッジを面取りします。0にすると、Gridfinityの仕様の図のようにとがったままです。",
  "prop.gridfinityMagnets": "磁石の穴",
  "prop.gridfinityHalfGrid": "半分のグリッド（21 mm）",
  "gridfinity.halfGridHint": "横と奥行きのマス数を21 mmのマスで数え、マスごとに足が1つずつ付きます。ベースプレートの1つのくぼみに4つ入ります。",
  "prop.gridfinityLargePlate": "大きなベースプレート（最大12マス）",
  "gridfinity.largePlateHint": "横と奥行きを6マスではなく最大12マスにします。256 mmより大きいプリントベッド向けです。設定でプリンターを選んでいると、そのベッドより大きいプレートには印が付きます。",
  "prop.gridfinitySwallowtail": "Swallowtail",
  "gridfinity.swallowtailHint": "Swallowtail: プレートを厚さ2.4 mmの床にのせ、高さを7.4 mmにします。余白のない各辺の下にはポケットが半分ずつあり、2枚を並べると継ぎ目をまたいで丸ごとのポケットができます。下から押しこんだ連結ピースがカチッとはまり、2枚をつなぎます。「連結ピースを追加」で、奥と右のポケットごとに1つずつ作るので、次のプレートとの継ぎ目をまたぐポケットのすべてに1つずつ行きわたります。",
  "prop.gridfinitySwallowtailClearance": "連結ピースのクリアランス",
  "gridfinity.swallowtailClearanceHint": "各連結ピースが、どの辺でもポケットよりどれだけ小さいかです。連結ピースが詰まったり割れたりするときは大きく、ゆるいときは小さくします。0.15 mmまで上げられます。変わるのはプレートではなく、次に「連結ピースを追加」で作る連結ピースなので、変更したら「連結ピースを追加」をもう一度クリックしてください。",
  "prop.gridfinityFloorHeight": "底の高さ",
  "gridfinity.floorHeightHint": "ビンの底からこの高さまでが、中までつまっています。シェイプを切り取るための材料になります。",
  "gridfinity.floorHeightLipHint": "ビンの底からこの高さまでが、中までつまっています。シェイプを切り取るための材料になります。{height} mmまでは、上に別のビンを重ねられます。それより高くすると、重ねるためのふちもつまって、上面が平らになります。",
  "prop.gridfinityWallThickness": "壁の厚さ",
  "gridfinity.wallThicknessHint": "壁を厚くしても外側の大きさは変わらず、中がせまくなります。重ねるためのふちがあるときは、1.75 mmより厚い壁は、ビンの上のはし（高さのマス数×7 mm）より0.85 mm下で平らな段になって止まります。こうすると、上に重ねたビンの足に当たりません。",
  "prop.gridfinityOpenBack": "奥を開ける",
  "prop.gridfinityOpenFront": "手前を開ける",
  "prop.gridfinityOpenLeft": "左を開ける",
