  "prop.gridfinityOpeningDistanceBack": "奥の距離",
  "prop.gridfinityOpeningDistanceFront": "手前の距離",
  "prop.gridfinityOpeningDistanceLeft": "左の距離",
  "prop.gridfinityOpeningDistanceRight": "右の距離",
  "gridfinity.openingHint": "深さはふちの上（ふちがないときはビンの上）から、距離は開口部をそろえる端からはかります。幅いっぱいに底まで開けると、その側はすべて開きます。それより小さい開口部では、その側の角と横のふちが残ります。",
  "prop.gridfinityOpeningCorner": "開口部の角",
  "prop.gridfinityOpeningCornerSize": "開口部の角の大きさ",
  "gridfinity.openingCornerHint": "壁の外から見た、開口部の上と下の角です。0.5 mmより小さいと四角いままです。側面全体に開けた開口部には、上の角はありません。",
  "prop.gridfinityPaddingBack": "奥の余白",
  "prop.gridfinityPaddingFront": "手前の余白",
  "prop.gridfinityPaddingLeft": "左の余白",
  "prop.gridfinityPaddingRight": "右の余白",
  "gridfinity.paddingHint": "グリッドの外側にある、中までつまったふちです。マスの数でちょうど割り切れない引き出しも、ベースプレートでうめられます。余白を変えると、マスの数はそのままで、プレートの大きさが変わります。",
  "prop.gridfinityCornerRadius": "角の半径",
  "gridfinity.cornerRadiusHint": "プレートの外側の4つの角の半径です。Gridfinityの仕様の図では4 mmで、0にすると引き出しの角にぴったり入る四角い角になります。くぼみの丸みは変わらないので、ビンはこれまでどおり入ります。",
  "gridfinity.binCornerRadiusHint": "ビンの足より上の、外側の角の半径です。Gridfinityの仕様の図では3.75 mmです。0まで小さくすると角が四角になり、引き出しにならべたとき、4つのビンが集まるところにも0.5 mmのすき間しか残りません。足、内側、上に重ねたビンがのるふちの斜面は丸いままなので、ビンはこれまでどおりベースプレートにはまり、重ねられます。",
  "prop.gridfinityDrawerWidth": "引き出しの幅",
  "prop.gridfinityDrawerDepth": "引き出しの奥行き",
  "gridfinity.drawerHint": "引き出しの内側の大きさです。プレートはこれより0.5 mm小さくなります。{size} mmより大きい引き出しや、プリントベッドより大きい引き出しには、ベースプレートが何枚か必要です。",
  "prop.gridfinityOutline": "輪郭に合わせ済み",
  "gridfinity.outlineCells": "輪郭の中に{cells}マス、残りは中実です。輪郭をオフにすると、余白付きの欠けのないマスのプレートに戻ります。",
  "gridfinity.outlineNoCells": "輪郭が42 mmの1マスより小さいため、中実のプレートです。輪郭をオフにすると、余白付きの欠けのないマスのプレートに戻ります。",
  "gridfinity.outlineNeedsLargePlate": "輪郭の幅か奥行きが{size} mmを超えている間は「大きなベースプレート」はオンのままです。オフにするには輪郭を小さくしてください。",
  "gridfinity.outlineFitHint": "長方形でない引き出しには、プレートと引き出しの内側の形を一緒に選び、「ベースプレートを輪郭に合わせる」を使います。",
  "inspector.gridfinityOutlineFit": "ベースプレートを輪郭に合わせる",
  "inspector.gridfinityOutlineFitHint": "もう一方の形が置かれている部分を、0.25 mm内側で42 mmの欠けのないマスで埋め、残りを中実にします。プレートはそこへ移動し、もう一方の形はそのまま残ります。",
  "status.gridfinityOutlineReading": "輪郭を読み取っています…",
  "status.gridfinityOutlineFitted": "ベースプレートを輪郭に合わせました: {cells}マス、残りは中実です。",
  "status.gridfinityOutlineNoOutline": "作業平面上にベースプレートを合わせる輪郭がありません。先に形を作業平面に置いてください。",
  "status.gridfinityOutlineSeveral": "輪郭が複数の部分に分かれていますが、ベースプレートが埋めるのは1つです。形を1つにするか、先に結合してください。",
  "status.gridfinityOutlineTooLarge": "輪郭がベースプレート1枚に収まる大きさを超えています: 幅と奥行きは最大{size} mmです。斜めの引き出しなら先にプレートを合わせて回転させ、そうでなければ複数のプレートを使ってください。",
  "status.gridfinityOutlineTooLargeSwitch": "輪郭が「大きなベースプレート」なしのベースプレート1枚に収まる大きさを超えています: 幅と奥行きは最大{size} mmです。「大きなベースプレート」をオンにすると最大{large} mmまでになります。",
  "status.gridfinityOutlineTooSmall": "輪郭がベースプレートの最小サイズより小さいです: 幅と奥行きは最低{size} mmです。",
  "status.gridfinityOutlineTooComplex": "輪郭の点が多すぎてベースプレートにできません: 最大{count}点です。もっと単純な形を使ってください。",
  "status.gridfinityOutlineTilted": "輪郭に合わせるには、ベースプレートが作業平面に平らに置かれている必要があります。",
  "status.gridfinityOutlineChanged": "輪郭を読み取っている間にデザインが変わりました。もう一度お試しください。",
  "inspector.gridfinityKeys": "連結ピースを追加",
  "gridfinity.swallowtailKey": "Swallowtailの連結ピース",
  "status.gridfinityKeysMade": "連結ピースを{count}個追加しました。プレートの手前にあり、そのまま印刷できます。それぞれを下から、継ぎ目をまたぐポケットにカチッとはまるまで押しこんでください。",
  "status.gridfinityKeysNone": "このプレートは奥と右に余白があるため、そこにポケットがなく、連結ピースはありません。そのどちらかの余白を0にすると、ポケットができます。",
  "status.gridfinityKeysChanged": "連結ピースを作っている間にデザインが変わりました。もう一度お試しください。",
