  "surfaceTexture.carbonTwill31": "綾織り 3/1",
  "surfaceTexture.carbonTwill22Hint": "どの帯も、交わる帯の2本の上を通り、2本の下を通ります。たいていのカーボンパーツに見られる、そろったななめ模様です。",
