  "inspector.surfaceCarbonCross": "交わる帯の幅",
  "inspector.surfaceCarbonHint": "交わる帯の幅が0なら、たての帯と同じ幅です。広くしたりせまくしたりすると、ふぞろいな織り目になります。ボディのまわりでは、織り目が閉じるように、帯の幅を少し丸めます。",
