  "inspector.surfaceImageHint": "明るいところがいちばん深くなり、暗いところはそのままです。SVGの黒い線のように、すき通った背景に暗い絵をかいたものは線を見て、線がいちばん深くなります。自分の画像はグレーにして、1辺256点までの大きさでデザインといっしょに保存します。タイルの幅は設定した幅で、高さはその幅に合わせた画像の高さです。",
