  "surfaceTexture.woodCutLogHint": "木のしんがボディのまん中を上に通ります。両はしには年輪が、側面には皮をむいた丸太の木目が出ます。",
  "surfaceTexture.woodCutFlatSawnHint": "木のしんが、板のいちばん長い辺にそって板の下を通ります。年輪が板の面にアーチの形で出ます。",
  "surfaceTexture.woodCutQuarterSawnHint": "木のしんが板の横を通ります。年輪が板の面にまっすぐな線で出て、オークでは、中心から外へのびるすじが点のもようになって見えます。",
