  "vaseCheck.watertightVaseMode": "花びんモードで水がもれないようにするには: 線を太く（0.4 mmノズルで約0.6〜0.8 mm）して温度を少し上げると、1枚の壁でももれにくくなります。内側のリブや二重の壁で、じょうぶにできます。先に流しの上で水を入れてためしてください。",
