  "vaseCheck.lampStanding": "置き型: ランプのソケットを底の穴（直径{mm} mm）にシェードリングでとめます。コードは中空の足を通ります。ソケットの本体が下に入るように、足を十分高くしてください。測ってたしかめてください。",
