  "export.stlNewFile": "{name}の保存先をたずねます",
  "export.stlSaveAs": "名前を付けて保存…",
  "export.3mf.description": "色付きのスライサープロジェクト",
  "export.3mf.note": "PrusaSlicer、Bambu Studio、OrcaSlicer、Cura向けです。各ボディは名前と色を保ったまま別々のパーツになります。",
  "export.obj.description": "汎用3Dメッシュ",
  "export.obj.note": "モデリング、レンダリング、データ交換に広く使えるメッシュ形式です。色は頂点に保存され、Bambu StudioとOrcaSlicerが読み取れます。",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "直方体、円柱、球、円錐を正確なCADジオメトリとして保ちます。エッジを丸めたり面取りしたものや、STEPとして読み込んだボディも同じです。ねじ、ばね、歯車も正確なボディとしてエクスポートされます。テーパー、傾き、ねじりのあるシェイプも正確にエクスポートされます。テキストも、フォント本来の曲線で1文字ずつ正確にエクスポートされます。読み込んだメッシュは正確なボディに変換して書き出され、平面・円柱・円錐・球・トーラスが本物の面になります。フィギュアのような自由曲面のメッシュはSTLとしてエクスポートされます。",
  "export.svg.description": "上面図のベクター",
  "export.svg.note": "穴や曲線の輪郭を含む、ミリメートル単位のきれいな上面図のシルエットをエクスポートします。",
  "export.svg.noteFootprint": "オブジェクトが作業面に接している輪郭だけを、ミリ単位の線として書き出します。レーザー加工や型紙に使えます。",
  "export.svg.noteEdges": "上から見えるエッジを、ミリ単位の線として、各ボディを自分の色で書き出します。輪郭、穴、ポケット、彫刻など、どの領域も閉じていて、レーザー彫刻やプロッターに使えます。",
  "export.svg.view": "表示",
  "export.svg.viewSilhouette": "上から見たシルエット",
  "export.svg.viewFootprint": "作業面への接地面",
  "export.bridges": "落ちてしまうパーツにブリッジを付ける",
  "export.bridgesHint": "切り抜きの内側にあるパーツ（「o」のまん中、「b」のふくらみの中）は、まわりを切ると落ちてしまいます。ステンシルのように、小さなブリッジでその場所につなぎとめます。",
  "export.bridgeWidth": "ブリッジの幅",
  "export.bridgeCount": "パーツごとのブリッジの数",
  "export.svg.viewEdges": "上から見える辺",
  "export.dxf.description": "レーザー加工用の輪郭",
  "export.dxf.note": "レーザー加工のお店向けに、上から見た輪郭を書き出します。線、本物の円弧と円を、レイヤー0に白で、ミリメートル単位で書きます。ふれ合っているボディは1つの輪郭になります。",
  "export.dxf.noteFootprint": "レーザー加工のお店向けに、オブジェクトが作業平面に接している輪郭だけを書き出します。線、本物の円弧と円を、レイヤー0に白で、ミリメートル単位で書きます。",
  "export.lyl.description": "layerling独自のデザイン形式",
  "export.lyl.note": "編集できるデザイン、元に戻す/やり直す履歴、スケッチ、グループ、CADデータ、読み込み元を保ちます。古い.skfファイルも開けて、.lylとして保存されます。ChromeとEdgeではフォルダーと名前を自分で選び、次からCtrl+Sでそのファイルに再び保存されます。ファイルから開いたデザインはそのファイルに保存し直されます。",
  "import.openProject": "layerlingデザインを開く",
  "import.openProjectHint": "layerlingデザイン（.lyl、または古い.skf）を新しいローカルのデザインとして復元します",
  "import.insertProject": "このデザインに挿入",
  "import.insertProjectHint": "layerlingデザイン（.lyl）のボディをここにあるものに追加します。繰り返し使う基本パーツなどに便利です",
  "import.divider": "またはジオメトリを追加",
